<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= esc($title) ?> | Puihaha Electric</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="<?= base_url('style/dashboard.css') ?>"></head>
<body><div class="app-shell"><header class="topbar"><a class="brand" href="<?= base_url('dashboard') ?>"><span class="brand-mark"><i class="bi bi-lightning-charge-fill"></i></span><span>Puihaha<br><small>Electric Company</small></span></a><a class="logout" href="<?= base_url('dashboard') ?>"><i class="bi bi-arrow-left"></i> Back to dashboard</a></header><main class="content narrow"><div class="page-heading"><div><p class="eyebrow">CUSTOMER ACCOUNT</p><h1><?= esc($title) ?></h1><p class="subheading">Enter the customer information below.</p></div></div><?php if ($message = session()->getFlashdata('error')): ?><div class="notice error"><i class="bi bi-exclamation-circle-fill"></i><?= esc($message) ?></div><?php endif; ?><section class="panel form-panel"><form method="post" action="<?= $account ? base_url('account/' . $account['id'] . '/edit') : base_url('account/create') ?>"><?= csrf_field() ?><div class="form-grid"><label>Account number<input name="account_number" required maxlength="50" value="<?= esc(old('account_number', $account['account_number'] ?? '')) ?>"></label><label>Customer name<input name="customer_name" required maxlength="150" value="<?= esc(old('customer_name', $account['customer_name'] ?? '')) ?>"></label><label class="full">Address<textarea name="address" required rows="3"><?= esc(old('address', $account['address'] ?? '')) ?></textarea></label><label>Phone<input name="phone" maxlength="20" value="<?= esc(old('phone', $account['phone'] ?? '')) ?>"></label><label>Email<input type="email" name="email" maxlength="100" value="<?= esc(old('email', $account['email'] ?? '')) ?>"></label><label>Meter number<input name="meter_number" maxlength="50" value="<?= esc(old('meter_number', $account['meter_number'] ?? '')) ?>"></label><label>Connection type<select name="connection_type" required><?php $currentType = old('connection_type', $account['connection_type'] ?? 'residential'); ?><option value="residential" <?= $currentType === 'residential' ? 'selected' : '' ?>>Residential</option><option value="commercial" <?= $currentType === 'commercial' ? 'selected' : '' ?>>Commercial</option><option value="industrial" <?= $currentType === 'industrial' ? 'selected' : '' ?>>Industrial</option></select></label><label>Status<select name="status" required><?php $currentStatus = old('status', $account['status'] ?? 'active'); ?><option value="active" <?= $currentStatus === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $currentStatus === 'inactive' ? 'selected' : '' ?>>Inactive</option><option value="suspended" <?= $currentStatus === 'suspended' ? 'selected' : '' ?>>Suspended</option></select></label></div><div class="form-actions"><a class="button light" href="<?= base_url('dashboard') ?>">Cancel</a><button class="button primary" type="submit"><i class="bi bi-check-lg"></i> Save account</button></div></form></section></main></div></body></html>
